set-variable.value:
@{
      var jwt = (Jwt)context.Variables["validated-jwt"];
      var oid = jwt.Claims.GetValueOrDefault("oid", "");
      var tid = jwt.Claims.GetValueOrDefault("tid", "");
      var config = JObject.Parse((string)context.Variables["configuration"]);
      if (!Regex.IsMatch(oid, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$") ||
          !String.Equals(tid, (string)config["tenantId"], StringComparison.OrdinalIgnoreCase)) { return ""; }
      return oid.ToLowerInvariant();
    }

@{
      var config = JObject.Parse((string)context.Variables["configuration"]);
      var oid = (string)context.Variables["caller-id"];
      var matches = ((JArray)config["callerMappings"]).Where(m => String.Equals((string)m["objectId"], oid, StringComparison.OrdinalIgnoreCase)).ToArray();
      if (matches.Length != 1) { return "{}"; }
      var mapping = matches[0];
      if (mapping["tokensPerMinute"] == null || mapping["tokenQuota"] == null ||
          mapping["tokensPerMinute"].Type != JTokenType.Integer || mapping["tokenQuota"].Type != JTokenType.Integer ||
          (long)mapping["tokensPerMinute"] <= 0 || (long)mapping["tokenQuota"] <= 0 ||
          !new [] { "Hourly", "Daily", "Weekly", "Monthly", "Yearly" }.Contains((string)mapping["tokenQuotaPeriod"])) { return "{}"; }
      return mapping.ToString();
    }

@{
      if (context.Request.Method != "POST" || context.Request.Url.Path != "/__API_PATH__/v1/responses" ||
          !String.IsNullOrEmpty(context.Request.Url.QueryString)) { return "route-forbidden"; }
      var allowedHeaders = new [] {
        "authorization", "content-type", "content-length", "accept", "accept-encoding", "user-agent", "host", "connection",
        "x-forwarded-for", "keep-alive", "transfer-encoding",
        "traceparent", "tracestate", "x-correlation-id",
        "api-key", "ocp-apim-subscription-key", "x-project-id", "x-project", "x-ms-project-name", "x-tenant-id",
        "x-caller-id", "x-model", "x-backend-url", "x-stop-new-requests", "x-ms-client-request-id",
        "x-ms-model-mesh-model-name", "x-ms-model-id", "x-ms-deployment-name", "x-azureai-target-url",
        "x-ms-azureai-target-url", "x-apim-backend-id", "x-original-url", "x-rewrite-url" };
      if (context.Request.Headers.Keys.Any(h => !allowedHeaders.Contains(h.ToLowerInvariant()))) { return "header-forbidden"; }
      var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
      if (!String.Equals(contentType, "application/json", StringComparison.OrdinalIgnoreCase) || context.Request.Body == null) { return "invalid-body"; }
      var text = context.Request.Body.As<string>(preserveContent: true);
      if (Encoding.UTF8.GetByteCount(text) > 65536) { return "body-too-large"; }
      JToken token;
      try { token = JToken.Parse(text); }
      catch (Exception error) when (error.Source == "Newtonsoft.Json") { return "invalid-json"; }
      if (token.Type != JTokenType.Object) { return "invalid-body"; }
      var body = (JObject)token;
      var allowed = new [] { "model", "input", "max_output_tokens", "stream", "store" };
      if (body.Properties().Any(p => !allowed.Contains(p.Name))) { return "unsupported-body-field"; }
      if (body["model"] == null || body["model"].Type != JTokenType.String ||
          body["input"] == null || body["input"].Type != JTokenType.String || String.IsNullOrWhiteSpace((string)body["input"]) ||
          body["max_output_tokens"] == null || body["max_output_tokens"].Type != JTokenType.Integer) { return "invalid-body"; }
      var mapping = JObject.Parse((string)context.Variables["mapping"]);
      if (!((JArray)mapping["models"]).Any(m => String.Equals((string)m, (string)body["model"], StringComparison.Ordinal))) { return "model-forbidden"; }
      var maximum = (decimal)body["max_output_tokens"];
      if (maximum <= 0 || maximum > Math.Min((long)mapping["tokensPerMinute"], (long)mapping["tokenQuota"])) { return "invalid-output-limit"; }
      if (body["stream"] != null && body["stream"].Type != JTokenType.Boolean) { return "unsupported-stream"; }
      if (body["store"] != null && (body["store"].Type != JTokenType.Boolean || (bool)body["store"])) { return "storage-forbidden"; }
      return "approved";
    }

inbound.set-body:
@{
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      body["store"] = false;
      return body.ToString();
    }
